# DP over positions, state = (previous digit, partial sum)
# 7 positions, digits 0..9, sum exactly 30, no two adjacent equal.
from functools import lru_cache

import sys

# dp[d][s] = number of ways to fill positions up to current with last digit d and sum s
# init position 1
dp = [[0]*(31) for _ in range(10)]
for d in range(10):
    if d <= 30:
        dp[d][d] = 1

for pos in range(2, 8):
    ndp = [[0]*(31) for _ in range(10)]
    for prev in range(10):
        for s in range(31):
            v = dp[prev][s]
            if v == 0:
                continue
            for d in range(10):
                if d == prev:
                    continue
                if s + d <= 30:
                    ndp[d][s+d] += v
    dp = ndp

total = sum(dp[d][30] for d in range(10))
print('DP total:', total)
"
